def solve(g):
    g=[row[:] for row in g]
    cs=comps_of(g)
    singles=[c for c in cs if len(c)==1]
    blocks=[c for c in cs if len(c)>1]
    def dist(s,b):
        sy,sx=s[0][0],s[0][1]
        return min(abs(sy-y)+abs(sx-x) for y,x in b)
    for b in blocks:
        s=min(singles,key=lambda s:(dist(s,b),min(p[0] for p in b)-max(p[0] for p in s)))
        col=g[s[0][0]][s[0][1]]
